(function(){const api=globalThis.BeeTransactionRows;if(!api)return;
 function refit(){api.hydrate(document);}
 function modal(row,title,html){const host=row.closest('.bc-phone'),dialog=document.createElement('dialog'),saved={y:scrollY,overflow:document.body.style.overflow,focus:document.activeElement};dialog.className='c3-guide-dialog';dialog.innerHTML=`<header><span>${api.esc(title)}</span><button type="button" aria-label="关闭">×</button></header>${html}`;host.append(dialog);document.body.style.overflow='hidden';dialog.querySelector('header button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();document.body.style.overflow=saved.overflow;window.scrollTo(0,saved.y);saved.focus?.focus({preventScroll:true});});dialog.showModal();window.scrollTo(0,saved.y);dialog.querySelector('header button').focus({preventScroll:true});}
 function fields(row,r){const pairs=[['原币金额',r.hidden?'••••':r.amount],...(r.converted?[['历史折算',r.hidden?'••••':r.converted]]:[]),['分类',r.categoryLabel||r.title],['账户',r.accountName||'未设置'],['账本',r.ledgerName||'未提供'],['备注',r.note||r.title],['时间',(r.happenedAt||'').replace('T',' ')],['标签',r.tags.map(t=>t.label).join(' · ')||'未添加'],['附件',r.attachments||0],['统计规则',(r.status||[]).join(' · ')||'正常计入'],['访问状态',r.readOnly?'只读':'可编辑']];modal(row,'完整账单字段',`<dl class="c3-field-list">${pairs.map(([k,v])=>`<div><dt>${api.esc(k)}</dt><dd>${api.esc(v)}</dd></div>`).join('')}</dl>`);}
 document.addEventListener('click',e=>{const row=e.target.closest('.tx3');if(!row)return;const r=api.record(row);if(!r)return;e.preventDefault();e.stopImmediatePropagation();const target=e.target.closest('[data-c3-action]'),action=target?.dataset.c3Action;if(action==='metadata')return fields(row,r);if(action==='category')return modal(row,'分类详情',`<h3>${api.esc(r.categoryLabel||r.title)}</h3><p>分类图标与行编辑互相独立。</p>`);if(action==='tags')return modal(row,'全部标签',`<div class="sheet-tags">${r.tags.map(t=>`<span class="bc-tag" style="color:${t.color}">${api.esc(t.label)}</span>`).join('')}</div>`);if(action==='tag')return modal(row,'标签详情',`<h3>${api.esc(r.tags[Number(target.dataset.index)].label)}</h3>`);if(action==='attachments')return modal(row,'账单附件',`<p>${r.attachments}张固定合成凭证，不读取真实文件。</p><div class="c3-attachment-grid">${Array.from({length:r.attachments},(_,i)=>`<img src="../prototype/assets/attachment-payment.png" alt="付款凭证${i+1}" style="width:100%;border-radius:8px">`).join('')}</div>`);if(r.selected!==undefined){if(!r.readOnly){r.selected=!r.selected;row.classList.toggle('selected',r.selected);row.querySelector('.selection-circle').textContent=r.selected?'✓':'';}return;}fields(row,r);},true);
 document.addEventListener('contextmenu',e=>{const row=e.target.closest('.tx3');if(!row)return;const r=api.record(row);if(!r)return;e.preventDefault();fields(row,r);},true);
 document.addEventListener('keydown',e=>{const row=e.target.closest('.tx3');if(row&&!e.target.closest('button')&&['Enter',' '].includes(e.key)){e.preventDefault();row.click();}},true);
 window.addEventListener('resize',refit);document.querySelector('#spec-mode')?.addEventListener('change',refit);document.querySelector('#spec-accent')?.addEventListener('change',refit);requestAnimationFrame(refit);
})();
